"""Reviewer-owned literal parsing only; imports/runs no repository code."""
from pathlib import Path
import hashlib, json, re

ROOT = Path('/home/codex/.codex/worktrees/ec20/Proofs')
BASE = ROOT / 'Computability/BusyBeaver/Lean/BusyBeaver/ZFC'
OUT = Path('/tmp/zfc-ax-next-contract')
text = (BASE / 'Prog254.lean').read_text()
pat = re.compile(r'^  \(\.(node|decnz|inc|brk|cont|halt)(?: (\d+))?, \.(node|decnz|inc|brk|cont|halt)(?: (\d+))?\),? -- (\d+)$', re.M)
rows = {}
matches = pat.findall(text)
assert len(matches) == 6459
for a, x, b, y, index in matches:
    rows[int(index)] = ((a, int(x) if x else None), (b, int(y) if y else None))
assert sorted(rows) == list(range(6459))
leaves = []
def visit(edge, path):
    if edge[0] == 'node':
        for bit, child in enumerate(rows[edge[1]]): visit(child, path + [bit])
    else: leaves.append((path, edge))
visit(('node', 0), [])
assert len(leaves) == 6460
# Independent matching of the complete literal tree constructor token stream.
tokens = re.findall(r'\.node|\.leaf|\.decnz|\.inc|\.brk|\.cont|\.halt|\d+',
                    (BASE / 'ActualTree254.lean').read_text().split('def tree : Tree :=', 1)[1].split(' theorem tree_eq', 1)[0])
it = iter(tokens)
tree_leaves = []
def parse_tree(path):
    token = next(it)
    if token == '.node': parse_tree(path + [0]); parse_tree(path + [1])
    else:
        assert token == '.leaf'
        op = next(it)[1:]
        arg = None if op == 'halt' else int(next(it))
        tree_leaves.append((path, (op, arg)))
parse_tree([])
assert next(it, None) is None and tree_leaves == leaves
index_of = {(tuple(path), edge): i for i, (path, edge) in enumerate(leaves)}
def inc(path):
    out = path.copy()
    for i in range(len(out)-1, -1, -1):
        if out[i] == 0: out[i] = 1; break
        out[i] = 0
    return out
def strip(bit, k, path):
    out = path.copy()
    while k and out:
        if out.pop() == bit: k -= 1
    return out
def resolve(path):
    edge = ('node', 0); consumed = []; depth = 0
    while edge[0] == 'node':
        bit = path[depth] if depth < len(path) else 0
        consumed.append(bit); depth += 1
        edge = rows[edge[1]][bit]
    return index_of[(tuple(consumed), edge)]
bindings = []
for i in range(41, 137):
    path, (op, arg) = leaves[i]
    targets = {}
    if op in ('inc', 'decnz'): targets['positive' if op == 'decnz' else 'next'] = resolve(inc(path))
    if op == 'decnz': targets['zero'] = resolve(inc(strip(0, 1, path)))
    if op == 'brk': targets['break'] = resolve(inc(strip(0, arg, path)))
    if op == 'cont': targets['continue'] = resolve(strip(1, arg, path))
    bindings.append({'catalogue_index': i, 'represented_number': i+1,
                     'path_bits': ''.join(map(str, path)), 'edge': [op,arg], 'targets': targets})
pin_names = ['Prog254','ActualTree254','FiniteControlTable254','RegisterPath',
    'Permutation252Frame','ArithmeticControlAXPrefix254','ArithmeticControlPair254',
    'ArithmeticControlParamPush254','ArithmeticControlMP254','ArithmeticControlReadTemplate254',
    'ArithmeticControlUnpairCore254','ArithmeticControlRead254','ArithmeticControlUnpair254',
    'ArithmeticControlDispatch254','ArithmeticControlFetch254','ArithmeticControlRun254',
    'ArithmeticControlStep254','ArithmeticControlFrame254','ArithmeticControlClear254','ArithmeticCantor','ArithmeticCode254',
    'L2Axioms254','L2Macros254','L2Root254','L2AxiomsEval254','Enum254',
    'ArithmeticCommandStep254','ArithmeticTemplates254']
pins = {str(BASE / (name+'.lean')): hashlib.sha256((BASE / (name+'.lean')).read_bytes()).hexdigest() for name in pin_names}
result = {'status': 'SOURCE_ONLY_LITERAL_BINDINGS', 'scope': 'Reviewer-owned literal parsing; no Lean, supplied checker, or runtime execution.',
          'row_count': len(rows), 'leaf_count': len(leaves), 'entire_actual_tree_literal_matches': True,
          'source_sha256': pins, 'bindings': bindings}
(OUT/'literal-bindings.json').write_text(json.dumps(result, indent=2)+'\n')
for b in bindings:
    print(b['catalogue_index'], *b['edge'], b['targets'])
